import React from "react";
import { StyleSheet, Text, View, ScrollView } from "react-native";
import { Image } from "expo-image";
import { Icon } from "react-native-paper";

interface SankalpDocumentRendererProps {
  htmlContent: string;
}

function stripTags(html: string): string {
  return html.replace(/<[^>]+>/g, "").trim();
}

/**
 * Parses and renders rich formatted HTML generated by the Admin
 * Microsoft Word-style editor into beautiful native React Native components.
 * Supports headings, paragraphs, lists, styled tables, blockquotes, and media.
 */
export function SankalpDocumentRenderer({
  htmlContent,
}: SankalpDocumentRendererProps) {
  if (!htmlContent || typeof htmlContent !== "string") {
    return null;
  }

  // Tokenize HTML by block-level elements
  const blocks: React.ReactNode[] = [];
  const rawHtml = htmlContent.trim();

  // Regex matcher for block elements
  const blockRegex =
    /<(h[1-6]|p|ul|ol|table|blockquote|img|hr)([^>]*)>([\s\S]*?)<\/\1>|<(img|hr)([^>]*)\/?>/gi;

  let lastIndex = 0;
  let match: RegExpExecArray | null;
  let keyIndex = 0;

  while ((match = blockRegex.exec(rawHtml)) !== null) {
    const tagName = (match[1] || match[4] || "").toLowerCase();
    const attributes = match[2] || match[5] || "";
    const innerContent = match[3] || "";

    keyIndex++;

    if (tagName.startsWith("h")) {
      const level = parseInt(tagName.replace("h", ""), 10) || 2;
      const cleanText = stripTags(innerContent);
      if (cleanText) {
        blocks.push(
          <View key={`h-${keyIndex}`} style={styles.headingBlock}>
            <View style={styles.headingAccent} />
            <Text
              style={[
                styles.headingText,
                level === 1 && styles.h1,
                level === 2 && styles.h2,
                level >= 3 && styles.h3,
              ]}
            >
              {cleanText}
            </Text>
          </View>
        );
      }
    } else if (tagName === "p") {
      const isBold = /<strong>|<b>/i.test(innerContent);
      const cleanText = stripTags(innerContent);
      if (cleanText) {
        blocks.push(
          <Text
            key={`p-${keyIndex}`}
            style={[styles.paragraphText, isBold && styles.paragraphBold]}
          >
            {cleanText}
          </Text>
        );
      }
    } else if (tagName === "ul") {
      const liMatches = innerContent.match(/<li[^>]*>([\s\S]*?)<\/li>/gi) || [];
      if (liMatches.length > 0) {
        blocks.push(
          <View key={`ul-${keyIndex}`} style={styles.listContainer}>
            {liMatches.map((li, liIdx) => {
              const itemText = stripTags(li);
              if (!itemText) return null;
              return (
                <View key={`li-${liIdx}`} style={styles.listItemRow}>
                  <View style={styles.bulletDot} />
                  <Text style={styles.listItemText}>{itemText}</Text>
                </View>
              );
            })}
          </View>
        );
      }
    } else if (tagName === "ol") {
      const liMatches = innerContent.match(/<li[^>]*>([\s\S]*?)<\/li>/gi) || [];
      const marathiDigits = ["०", "१", "२", "३", "४", "५", "६", "७", "८", "९"];
      const toMarathi = (n: number) =>
        String(n)
          .split("")
          .map((d) => marathiDigits[parseInt(d, 10)] || d)
          .join("");

      if (liMatches.length > 0) {
        blocks.push(
          <View key={`ol-${keyIndex}`} style={styles.listContainer}>
            {liMatches.map((li, liIdx) => {
              const itemText = stripTags(li);
              if (!itemText) return null;
              return (
                <View key={`oli-${liIdx}`} style={styles.listItemRow}>
                  <View style={styles.numberBadge}>
                    <Text style={styles.numberBadgeText}>
                      {toMarathi(liIdx + 1)}
                    </Text>
                  </View>
                  <Text style={styles.listItemText}>{itemText}</Text>
                </View>
              );
            })}
          </View>
        );
      }
    } else if (tagName === "table") {
      // Parse Table Rows and Cells
      const rowMatches =
        innerContent.match(/<tr[^>]*>([\s\S]*?)<\/tr>/gi) || [];

      if (rowMatches.length > 0) {
        blocks.push(
          <View key={`tbl-${keyIndex}`} style={styles.tableCard}>
            <ScrollView horizontal showsHorizontalScrollIndicator={false}>
              <View style={styles.tableInner}>
                {rowMatches.map((tr, rIdx) => {
                  const isHeader =
                    rIdx === 0 && (/<th/i.test(tr) || /<thead>/i.test(innerContent));
                  const cells =
                    tr.match(/<(?:td|th)[^>]*>([\s\S]*?)<\/(?:td|th)>/gi) || [];

                  return (
                    <View
                      key={`tr-${rIdx}`}
                      style={[
                        styles.tableRow,
                        isHeader ? styles.tableHeaderRow : styles.tableBodyRow,
                        rIdx % 2 === 1 && !isHeader && styles.tableStripedRow,
                      ]}
                    >
                      {cells.map((cell, cIdx) => {
                        const cellText = stripTags(cell);
                        return (
                          <View
                            key={`cell-${cIdx}`}
                            style={[
                              styles.tableCell,
                              isHeader && styles.tableHeaderCell,
                            ]}
                          >
                            <Text
                              style={[
                                styles.cellText,
                                isHeader && styles.headerCellText,
                              ]}
                            >
                              {cellText}
                            </Text>
                          </View>
                        );
                      })}
                    </View>
                  );
                })}
              </View>
            </ScrollView>
          </View>
        );
      }
    } else if (tagName === "blockquote") {
      const quoteText = stripTags(innerContent);
      if (quoteText) {
        blocks.push(
          <View key={`quote-${keyIndex}`} style={styles.blockquoteContainer}>
            <Icon source="format-quote-close" size={24} color="#EA580C" />
            <Text style={styles.blockquoteText}>{quoteText}</Text>
          </View>
        );
      }
    } else if (tagName === "img") {
      const srcMatch = attributes.match(/src=["']([^"']+)["']/i);
      if (srcMatch && srcMatch[1]) {
        blocks.push(
          <View key={`img-${keyIndex}`} style={styles.mediaContainer}>
            <Image
              source={{ uri: srcMatch[1] }}
              style={styles.contentImage}
              contentFit="cover"
              transition={200}
            />
          </View>
        );
      }
    } else if (tagName === "hr") {
      blocks.push(<View key={`hr-${keyIndex}`} style={styles.divider} />);
    }

    lastIndex = blockRegex.lastIndex;
  }

  // Fallback if no supported HTML tags matched
  if (blocks.length === 0) {
    const rawClean = stripTags(rawHtml);
    return (
      <View style={styles.container}>
        <Text style={styles.paragraphText}>{rawClean}</Text>
      </View>
    );
  }

  return <View style={styles.container}>{blocks}</View>;
}

